import isString from "./utils/isString.js";
export const isHexString = (value) => {
    return isString(value) && value.length % 2 === 0 && /^[0-9a-f]*$/.test(value);
};
export const toHex = (arr) => {
    return Array.from(arr)
        .map(byte => byte.toString(16).padStart(2, "0"))
        .join("");
};
export const fromHex = (hex) => {
    if (isHexString(hex) === false) {
        throw new Error(`Invalid HexString: ${hex}`);
    }
    // padStart ensures even length
    const s = hex.length % 2 === 0 ? hex : "0" + hex;
    const bytes = [];
    for (let i = 0; i < s.length; i += 2) {
        bytes.push(parseInt(s.slice(i, i + 2), 16));
    }
    return new Uint8Array(bytes);
};
